import { maskCode, maskFrontmatter, maskNonMarkup, toPosition } from '../../mdx.js';
import type { FileRule, FileFinding } from '../../types.js';

type Pattern = {
  regex: RegExp;
  scope?: 'prose' | 'links' | 'prose-and-esm' | 'everything';
  message: (match: RegExpMatchArray) => string;
};

const CALLOUTS: Record<string, string> = {
  note: '<Note>',
  info: '<Info>',
  tip: '<Tip>',
  hint: '<Tip>',
  success: '<Check>',
  important: '<Note>',
  warning: '<Warning>',
  caution: '<Warning>',
  danger: '<Warning>',
  error: '<Warning>',
  details: '<Accordion>',
};

const callout = (name: string | undefined) =>
  CALLOUTS[name?.toLowerCase() ?? ''] ?? 'a callout (<Note>, <Info>, <Tip> or <Warning>)';

const LIQUID_TAGS: Record<string, string> = {
  hint: 'a callout (<Note>, <Info>, <Tip> or <Warning>)',
  tabs: '<Tabs>',
  tab: '<Tab title="…">',
  stepper: '<Steps>',
  step: '<Step title="…">',
  embed: 'a link or <Frame>',
  'content-ref': '<Card>',
  include: 'a snippet import',
  code: 'a fenced code block',
  file: 'a link to the file',
  swagger: 'an OpenAPI page',
  openapi: 'an OpenAPI page',
};

const PATTERNS: Pattern[] = [
  {
    regex: /\{%-?\s*(?!end)([\w-]+)[^%\n]*?-?%\}/g,
    message: ([tag, name]) => {
      const style = name === 'hint' ? /style=["']?(\w+)/.exec(tag)?.[1] : undefined;
      const target = style
        ? callout(style)
        : (LIQUID_TAGS[name ?? ''] ?? 'Markdown or a Mintlify component');
      return `${tag} is a GitBook or Liquid tag, which Mintlify does not support; use ${target}`;
    },
  },
  {
    regex: /\{\{[<%]\s*([\w/-]+)[^}\n]*[>%]\}\}/g,
    message: ([tag]) =>
      `${tag} is a Hugo shortcode, which Mintlify does not support; use Markdown or a Mintlify component`,
  },
  {
    regex:
      /\{\{-?\s*(?:(?:site|page|layout|include|jekyll|paginator)\.[^}\n]*|[^\s|{}]+\s*\|\s*\w+[^}\n]*)-?\}\}/g,
    message: ([tag]) =>
      `${tag} is a Liquid variable, which Mintlify does not support; write the value, or use a snippet or a variable`,
  },
  {
    regex: /^ {0,3}:{3,}\s*([A-Za-z][\w-]*)/gm,
    message: ([, name]) =>
      `:::${name} is a Docusaurus or VitePress admonition, which Mintlify does not support; use ${callout(name)}`,
  },
  {
    regex: /^ {0,3}::(?!:)([A-Za-z][\w-]*)/gm,
    message: ([, name]) =>
      `::${name} is an MDC (Nuxt Content, Docus) block, which Mintlify does not support; use the matching Mintlify component`,
  },
  {
    regex: /^ {0,3}(!!!|\?\?\?\+?)[ \t]+([A-Za-z][\w-]*)/gm,
    message: ([, marker, name]) =>
      `${marker} ${name} is an MkDocs admonition, which Mintlify does not support; use ${
        marker === '!!!' ? callout(name) : '<Accordion>'
      }`,
  },
  {
    regex: /^ {0,3}===\+?[ \t]+["']/gm,
    message: () =>
      `=== "…" is an MkDocs content tab, which Mintlify does not support; use <Tabs> with <Tab title="…">`,
  },
  {
    regex: /^[ \t]*;?[ \t]*--8<--/gm,
    scope: 'everything',
    message: () =>
      '--8<-- is an MkDocs snippet include, which Mintlify does not support; use a snippet import or paste the content',
  },
  {
    regex: /\{:\s*[.#\w][^}\n]*\}/g,
    message: ([list]) =>
      `${list} is a Kramdown attribute list, which Mintlify does not support; remove it, use a component, or use {#id} for a heading anchor`,
  },
  {
    regex: /(?<![[{\w])\[\[([^[\]\n]+)\]\](?![(:[])/g,
    message: ([link]) =>
      `${link} is a wiki link, which Mintlify does not support; use a Markdown link such as [text](/path)`,
  },
  {
    regex: /(?:\]\(|href=["'])((?:doc|ref|blog|changelog|page):[^)\s"']+)/g,
    scope: 'links',
    message: ([, link]) =>
      `${link} is a ReadMe link, which Mintlify does not support; link to the page path instead, such as /${
        link?.split(':')[1] ?? ''
      }`,
  },
  {
    regex: /["'(]@site\/[^"')\s]*/g,
    scope: 'prose-and-esm',
    message: ([path]) =>
      `${path.slice(1)} uses the Docusaurus @site alias, which Mintlify does not resolve; use a root-relative path such as /images/… or /snippets/…`,
  },
];

export const foreignSyntax: FileRule = {
  id: 'foreign-syntax',
  group: 'content',
  severity: 'warning',
  scope: 'file',
  description: "syntax from another docs framework that Mintlify doesn't render",
  raw: true,
  check: ({ content }) => {
    const prose = maskCode(content);
    const literal = maskNonMarkup(content);
    const views = {
      prose,
      links: prose,
      'prose-and-esm': maskCode(content, { keepEsm: true }),
      everything: maskFrontmatter(content),
    };
    const issues: FileFinding[] = [];
    for (const { regex, scope = 'prose', message } of PATTERNS) {
      for (const match of views[scope].matchAll(regex)) {
        const start = match.index + (match[0].length - match[0].trimStart().length);
        if (scope === 'prose' && literal[start] !== prose[start]) continue;
        issues.push({ ...toPosition(content, start), message: message(match) });
      }
    }
    return issues;
  },
};
